head.script:
(function () {
  try {
    var saved = localStorage.getItem('theme-preference');
    if (saved === 'dark') {
      document.documentElement.classList.add('dark-mode');
    } else if (saved === 'light') {
      document.documentElement.classList.remove('dark-mode');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      document.documentElement.classList.add('dark-mode');
    }
  } catch (e) {}
})();

head.b:skin:
:root {
  --bg: #f5f7fb;
  --bg-strong: #eef3ff;
  --card: #ffffff;
  --card-alt: #f8faff;
  --text: #172033;
  --text-soft: #5d6b82;
  --text-faint: #7a8799;
  --line: rgba(23, 32, 51, 0.10);
  --shadow: 0 18px 48px rgba(21, 31, 54, 0.08);
  --shadow-soft: 0 8px 24px rgba(21, 31, 54, 0.06);
  --shadow-xs: 0 4px 12px rgba(21, 31, 54, 0.04);
  --accent: #3563ff;
  --accent-strong: #214fe7;
  --accent-soft: rgba(53, 99, 255, 0.12);
  --success: #2cc990;
  --warning: #ffc857;
  --danger: #ef476f;
  --radius: 22px;
  --radius-sm: 14px;
  --radius-xs: 10px;
  --container: 1180px;
  --header-height: 88px;
  --transition: 180ms ease;
  --transition-fast: 120ms ease;
  --font-display: 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  --font-body: 'Inter', 'Segoe UI', sans-serif;
}

html.dark-mode,
body.dark-mode {
  --bg: #0f172a;
  --bg-strong: #121d31;
  --card: #152238;
  --card-alt: #1a2942;
  --text: #edf3ff;
  --text-soft: #b3c0d9;
  --text-faint: #8da0bf;
  --line: rgba(148, 163, 184, 0.18);
  --shadow: 0 18px 48px rgba(2, 6, 23, 0.42);
  --shadow-soft: 0 10px 30px rgba(2, 6, 23, 0.34);
  --shadow-xs: 0 4px 12px rgba(2, 6, 23, 0.24);
  --accent: #9ab4ff;
  --accent-strong: #c4d3ff;
  --accent-soft: rgba(154, 180, 255, 0.12);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: linear-gradient(180deg, var(--bg) 0%, var(--bg-strong) 100%);
  color: var(--text);
  font-family: var(--font-body);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  transition: background-color var(--transition), color var(--transition);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-strong);
}

a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

::selection {
  background: rgba(53, 99, 255, 0.22);
  color: var(--text);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.container {
  width: min(var(--container), calc(100% - 32px));
  margin: 0 auto;
}

.page-shell {
  min-height: 100vh;
}

.progress-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: transparent;
  z-index: 2000;
  pointer-events: none;
}

.progress-bar {
  width: 0;
  height: 100%;
  background: linear-gradient(90deg, var(--accent), #71b6ff);
  box-shadow: 0 0 18px rgba(53, 99, 255, 0.5);
  transition: width 0.16s ease-out;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 1200;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  background: rgba(255, 255, 255, 0.78);
  border-bottom: 1px solid var(--line);
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.03);
  transition: background var(--transition), border-color var(--transition);
}

html.dark-mode .topbar {
  background: rgba(15, 23, 42, 0.74);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: var(--header-height);
  padding: 0 16px;
}

.brand {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 10px 16px;
  background: linear-gradient(135deg, var(--accent) 0%, #6789ff 100%);
  color: #fff !important;
  border-radius: 14px;
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  box-shadow: 0 10px 22px rgba(53, 99, 255, 0.24);
  white-space: nowrap;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
  flex-shrink: 0;
}

.brand:hover {
  color: #fff !important;
  transform: translateY(-2px);
  box-shadow: 0 14px 28px rgba(53, 99, 255, 0.32);
}

.brand:active {
  transform: translateY(0);
}

.nav {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  justify-content: center;
}

.nav-list,
.nav-list ul,
.widget-content ul,
.post-body-content ul,
.post-body-content ol,
.sidebar ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.nav-list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.nav-list li {
  position: relative;
}

.nav-list a,
.nav-list .nav-dropdown-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 14px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.35);
  color: var(--text);
  font-size: 0.87rem;
  font-weight: 700;
  transition: all var(--transition);
  min-height: 42px;
}

.nav-list a:hover,
.nav-list .nav-dropdown-btn:hover,
.nav-list li:hover > a,
.nav-list li:hover > .nav-dropdown-btn {
  background: var(--accent-soft);
  border-color: rgba(53, 99, 255, 0.18);
  color: var(--accent);
  transform: translateY(-1px);
}

.dropdown {
  position: relative;
}

.dropdown-menu {
  position: absolute;
  top: calc(100% + 10px);
  left: 0;
  min-width: 220px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: var(--shadow-soft);
  padding: 10px;
  display: none;
  z-index: 30;
  animation: slideDown var(--transition-fast) ease-out;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.dropdown:hover .dropdown-menu,
.dropdown:focus-within .dropdown-menu,
.dropdown-menu.open {
  display: block;
}

.dropdown-menu a {
  display: block;
  padding: 9px 10px;
  border-radius: 10px;
  color: var(--text);
  background: transparent;
  font-weight: 600;
  min-height: 40px;
  display: flex;
  align-items: center;
  transition: all var(--transition-fast);
}

.dropdown-menu a:hover {
  background: var(--accent-soft);
  color: var(--accent);
  transform: translateX(2px);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.search-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.48);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 6px 8px 6px 12px;
  min-width: 260px;
  transition: all var(--transition-fast);
}

.search-wrap:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent-soft);
}

.search-wrap input {
  width: 100%;
  border: 0;
  background: transparent;
  color: var(--text);
  outline: 0;
  font-size: 0.92rem;
}

.search-wrap input::placeholder {
  color: var(--text-faint);
}

.search-btn,
.theme-toggle,
.mobile-menu-btn,
.toc-toggle-btn,
.share-btn,
.sidebar-tab-btn,
.pager-link,
.comment-reply {
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--text);
  border-radius: 12px;
  cursor: pointer;
  transition: all var(--transition);
  min-height: 42px;
}

.search-btn {
  background: linear-gradient(135deg, var(--accent) 0%, #6789ff 100%);
  border-color: transparent;
  color: #fff;
  padding: 8px 12px;
  font-weight: 700;
  transition: all var(--transition-fast);
}

.search-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(53, 99, 255, 0.3);
}

.search-btn:active {
  transform: translateY(0);
}

.theme-toggle,
.mobile-menu-btn {
  width: 42px;
  height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.theme-toggle {
  position: relative;
}

.theme-toggle::before {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 12px;
  background: transparent;
  transition: background var(--transition-fast);
}

.theme-toggle:hover::before {
  background: var(--accent-soft);
}

.theme-toggle span {
  position: relative;
  z-index: 1;
  display: inline-flex;
  transition: transform var(--transition-fast);
}

.theme-toggle.is-rotating span {
  animation: rotate 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

@keyframes rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.mobile-menu-btn {
  display: none;
}

.search-btn:hover,
.theme-toggle:hover,
.mobile-menu-btn:hover,
.toc-toggle-btn:hover,
.share-btn:hover,
.sidebar-tab-btn:hover,
.pager-link:hover,
.comment-reply:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-soft);
}

.main-layout {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(280px, 0.9fr);
  gap: 24px;
  padding-top: 28px;
  padding-bottom: 48px;
}

.content-area,
.sidebar {
  min-width: 0;
}

.card,
.widget-card,
.post-card,
.single-post,
.comments,
.sidebar-widget,
.toc-box {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow-soft);
  transition: all var(--transition);
}

.post-card {
  display: grid;
  grid-template-columns: minmax(200px, 300px) minmax(0, 1fr);
  overflow: hidden;
  margin-bottom: 22px;
}

.post-card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
  border-color: var(--accent-soft);
}

.post-card:focus-within {
  box-shadow: var(--shadow);
  border-color: var(--accent);
}

.post-thumb {
  position: relative;
  min-height: 220px;
  background: var(--bg-strong);
  overflow: hidden;
}

.post-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease-out;
}

.post-card:hover .post-thumb img {
  transform: scale(1.05);
}

.post-card-body {
  padding: 20px 22px 18px;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.post-category {
  display: inline-flex;
  align-self: flex-start;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(255, 200, 87, 0.22);
  color: #9a6a00;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 12px;
  transition: all var(--transition-fast);
}

.post-card:hover .post-category {
  background: rgba(255, 200, 87, 0.32);
  color: #b8840c;
}

.post-title {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-size: clamp(1.3rem, 2vw, 1.8rem);
  line-height: 1.25;
  font-weight: 800;
}

.post-title a {
  color: var(--text);
  transition: color var(--transition-fast);
}

.post-title a:hover {
  color: var(--accent);
}

.post-snippet {
  color: var(--text-soft);
  margin: 0 0 16px;
  font-size: 0.96rem;
  line-height: 1.6;
}

.post-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
  color: var(--text-faint);
  font-size: 0.78rem;
  font-weight: 600;
}

.meta-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-strong);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 6px 10px;
  transition: all var(--transition-fast);
}

.meta-item:hover {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
}

.single-post {
  padding: 28px 28px 20px;
}

.entry-title {
  margin: 0 0 16px;
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.2rem);
  line-height: 1.1;
  font-weight: 800;
  color: var(--text);
}

.entry-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  padding-bottom: 16px;
  margin-bottom: 18px;
  border-bottom: 1px solid var(--line);
  color: var(--text-soft);
  font-size: 0.8rem;
  font-weight: 700;
}

.reading-time {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  background: var(--accent-soft);
  border-radius: 8px;
  color: var(--accent);
  font-weight: 700;
}

.post-body-content,
.static-page-content {
  color: var(--text);
  font-size: 1.02rem;
  line-height: 1.8;
}

.post-body-content h1,
.post-body-content h2,
.post-body-content h3,
.post-body-content h4,
.static-page-content h1,
.static-page-content h2,
.static-page-content h3,
.static-page-content h4 {
  margin-top: 28px;
  margin-bottom: 12px;
  font-family: var(--font-display);
  line-height: 1.2;
  color: var(--text);
}

.post-body-content h2,
.static-page-content h2 {
  font-size: clamp(1.4rem, 2vw, 2rem);
}

.post-body-content h3,
.static-page-content h3 {
  font-size: clamp(1.2rem, 1.6vw, 1.5rem);
}

.post-body-content p,
.post-body-content li,
.static-page-content p,
.static-page-content li {
  color: var(--text);
  margin: 12px 0;
}

.post-body-content img,
.static-page-content img {
  display: block;
  max-width: 100%;
  margin: 18px auto;
  border-radius: 18px;
  box-shadow: var(--shadow-soft);
  transition: box-shadow var(--transition);
}

.post-body-content img:hover,
.static-page-content img:hover {
  box-shadow: var(--shadow);
}

.post-body-content a,
.static-page-content a {
  color: var(--accent);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
  transition: all var(--transition-fast);
}

.post-body-content a:hover,
.static-page-content a:hover {
  color: var(--accent-strong);
  text-decoration-thickness: 2px;
}

.post-body-content blockquote,
.static-page-content blockquote {
  margin: 22px 0;
  padding: 16px 18px;
  border-left: 4px solid var(--accent);
  background: var(--bg-strong);
  border-radius: 12px;
  color: var(--text-soft);
  font-style: italic;
  transition: all var(--transition-fast);
}

.post-body-content blockquote:hover,
.static-page-content blockquote:hover {
  border-left-color: var(--accent-strong);
  background: var(--accent-soft);
}

.toc-box {
  margin: 24px 0;
  padding: 18px 20px;
  border-left: 4px solid var(--accent);
  animation: fadeIn 0.4s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.toc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.toc-title {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 800;
  margin: 0;
  color: var(--text);
}

.toc-toggle-btn {
  padding: 8px 12px;
  font-size: 0.8rem;
  font-weight: 700;
  transition: all var(--transition-fast);
}

.toc-toggle-btn.collapsed::after {
  content: ' ▼';
}

.toc-toggle-btn:not(.collapsed)::after {
  content: ' ▲';
}

.toc-content {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
  max-height: 100vh;
  overflow: hidden;
  transition: max-height var(--transition), opacity var(--transition);
  opacity: 1;
}

.toc-content.collapsed {
  max-height: 0;
  opacity: 0;
  margin-top: 0;
  padding-top: 0;
  border-top: none;
}

.toc-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 8px;
}

.toc-list a {
  display: inline-block;
  color: var(--text-soft);
  font-weight: 600;
  padding: 4px 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.toc-list a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
  padding-left: 4px;
}

.toc-depth-h2 { margin-left: 0; }
.toc-depth-h3 { margin-left: 18px; }
.toc-depth-h4 { margin-left: 36px; }

.share-box {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 26px;
  padding-top: 18px;
  border-top: 1px dashed var(--line);
}

.share-label {
  font-family: var(--font-display);
  font-weight: 800;
  margin-right: 4px;
  color: var(--text);
}

.share-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 12px;
  font-size: 0.8rem;
  font-weight: 700;
  transition: all var(--transition-fast);
  min-height: auto;
}

.share-wa:hover { background: #25d366; color: #fff; border-color: #25d366; }
.share-fb:hover { background: #1877f2; color: #fff; border-color: #1877f2; }
.share-tw:hover { background: #1d9bf0; color: #fff; border-color: #1d9bf0; }

.comments {
  margin-top: 28px;
  padding: 24px 22px;
}

.comments-title {
  margin: 0 0 18px;
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--text);
}

.comment-body {
  padding: 14px 0;
  border-top: 1px solid var(--line);
  transition: background var(--transition-fast);
}

.comment-body:hover {
  background: var(--card-alt);
  padding: 14px 12px;
  margin: 0 -12px;
  border-radius: 8px;
}

.comment-author {
  font-weight: 800;
  color: var(--text);
}

.comment-date {
  color: var(--text-faint);
  font-size: 0.72rem;
}

.comment-content {
  color: var(--text-soft);
  margin-top: 6px;
  line-height: 1.6;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.sidebar-widget {
  padding: 18px 16px;
  transition: all var(--transition-fast);
}

.sidebar-widget:hover {
  box-shadow: var(--shadow);
}

.sidebar-title {
  margin: 0 0 14px;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 800;
  color: var(--text);
  position: relative;
  padding-bottom: 10px;
}

.sidebar-title::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 32px;
  height: 3px;
  background: var(--accent);
  border-radius: 999px;
}

.sidebar-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}

.sidebar-list a {
  display: block;
  padding: 8px 10px;
  border-radius: 10px;
  color: var(--text-soft);
  background: var(--bg-strong);
  border: 1px solid var(--line);
  font-weight: 600;
  transition: all var(--transition-fast);
  position: relative;
}

.sidebar-list a::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 0;
  background: var(--accent);
  border-radius: 999px;
  transition: height var(--transition-fast);
}

.sidebar-list a:hover {
  color: var(--accent);
  border-color: var(--accent);
  background: var(--accent-soft);
  padding-left: 14px;
}

.sidebar-list a:hover::before {
  height: 20px;
}

.sidebar-tabs {
  display: flex;
  gap: 8px;
  background: var(--bg-strong);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 6px;
  margin-bottom: 12px;
}

.sidebar-tab-btn {
  flex: 1;
  padding: 8px 12px;
  font-size: 0.8rem;
  font-weight: 800;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-soft);
  transition: all var(--transition-fast);
  border-radius: 10px;
  min-height: auto;
}

.sidebar-tab-btn:hover {
  background: var(--card);
  color: var(--text);
}

.sidebar-tab-btn.active {
  background: linear-gradient(135deg, var(--accent) 0%, #6789ff 100%);
  color: #fff;
  border-color: transparent;
  box-shadow: 0 4px 12px rgba(53, 99, 255, 0.3);
}

.sidebar-tab-panel {
  display: none;
  animation: fadeIn 0.3s ease-out;
}

.sidebar-tab-panel.active {
  display: block;
}

.pager {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 20px;
  flex-wrap: wrap;
}

.pager-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 0 16px;
  font-weight: 700;
  transition: all var(--transition-fast);
  min-height: auto;
}

.pager-link:hover {
  background: var(--accent-soft);
  color: var(--accent);
  border-color: var(--accent);
}

.pager .current {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 0 14px;
  border-radius: 12px;
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: 800;
  border: 1px solid var(--accent);
}

@media (max-width: 980px) {
  .header-inner {
    flex-wrap: wrap;
    justify-content: space-between;
    padding: 10px 16px;
  }

  .nav {
    order: 3;
    width: 100%;
    justify-content: center;
    display: none;
  }

  .nav.is-open {
    display: flex;
  }

  .main-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  :root {
    --header-height: 88px;
  }

  .header-inner {
    align-items: center;
    padding: 12px 16px;
  }

  .mobile-menu-btn {
    display: inline-flex;
    order: 2;
  }

  .nav {
    order: 3;
    width: 100%;
    justify-content: center;
    margin-top: 12px;
    border-top: 1px solid var(--line);
    padding-top: 12px;
  }

  .nav-list {
    flex-direction: column;
    width: 100%;
  }

  .nav-list li {
    width: 100%;
  }

  .nav-list a,
  .nav-list .nav-dropdown-btn {
    width: 100%;
    justify-content: center;
    min-height: 44px;
  }

  .search-wrap {
    min-width: 0;
    width: 100%;
    order: 4;
    margin-top: 12px;
  }

  .header-actions {
    width: 100%;
    order: 5;
    margin-top: 12px;
  }

  .post-card {
    grid-template-columns: 1fr;
  }

  .post-thumb {
    min-height: 200px;
  }

  .single-post {
    padding: 20px 18px 16px;
  }

  .container {
    width: min(var(--container), calc(100% - 16px));
  }

  .brand {
    order: 1;
  }
}

@media (max-width: 480px) {
  .search-wrap {
    min-width: 0;
  }

  .post-card-body {
    padding: 16px 14px 14px;
  }

  .single-post {
    padding: 16px 14px 12px;
  }

  .entry-title {
    font-size: clamp(1.5rem, 3vw, 2.2rem);
  }

  .post-title {
    font-size: clamp(1.1rem, 2vw, 1.5rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@supports (backdrop-filter: blur(1px)) {
  .topbar {
    background: rgba(255, 255, 255, 0.6);
  }

  html.dark-mode .topbar {
    background: rgba(15, 23, 42, 0.6);
  }
}

body.script:
document.addEventListener('DOMContentLoaded', function () {
  var body = document.body;
  var html = document.documentElement;
  var progressBar = document.getElementById('progressBar');
  var themeToggle = document.querySelector('.theme-toggle');
  var mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  var nav = document.querySelector('.nav');
  var searchInput = document.getElementById('search-input');

  function applyTheme(isDark) {
    html.classList.toggle('dark-mode', isDark);
    body.classList.toggle('dark-mode', isDark);

    if (themeToggle) {
      themeToggle.classList.add('is-rotating');
      setTimeout(function () {
        themeToggle.classList.remove('is-rotating');
      }, 600);

      var span = themeToggle.querySelector('span');
      if (span) {
        span.textContent = isDark ? '☀' : '☾';
      }
    }

    try {
      localStorage.setItem('theme-preference', isDark ? 'dark' : 'light');
    } catch (e) {}
  }

  if (themeToggle) {
    themeToggle.addEventListener('click', function () {
      var isDark = !html.classList.contains('dark-mode');
      applyTheme(isDark);
    });
  }

  var isDarkPreferred = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  var savedTheme = null;

  try {
    savedTheme = localStorage.getItem('theme-preference');
  } catch (e) {}

  if (savedTheme === 'dark' || (!savedTheme && isDarkPreferred)) {
    applyTheme(true);
  } else {
    applyTheme(false);
  }

  window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function (e) {
    var savedTheme = null;
    try {
      savedTheme = localStorage.getItem('theme-preference');
    } catch (err) {}

    if (!savedTheme) {
      applyTheme(e.matches);
    }
  });

  if (mobileMenuBtn && nav) {
    mobileMenuBtn.addEventListener('click', function () {
      var isOpen = nav.classList.contains('is-open');
      nav.classList.toggle('is-open');
      mobileMenuBtn.setAttribute('aria-expanded', !isOpen);
    });

    nav.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        nav.classList.remove('is-open');
        mobileMenuBtn.setAttribute('aria-expanded', 'false');
      });
    });
  }

  document.querySelectorAll('img').forEach(function (img) {
    if (!img.hasAttribute('loading')) {
      img.setAttribute('loading', 'lazy');
    }
    if (!img.hasAttribute('decoding')) {
      img.setAttribute('decoding', 'async');
    }
  });

  if (progressBar) {
    function updateProgress() {
      var scrollTop = window.scrollY || html.scrollTop;
      var maxScroll = html.scrollHeight - window.innerHeight;
      var ratio = maxScroll > 0 ? (scrollTop / maxScroll) * 100 : 0;
      progressBar.style.width = Math.min(Math.max(ratio, 0), 100) + '%';
    }

    updateProgress();
    window.addEventListener('scroll', updateProgress, { passive: true });
  }

  var tocToggle = document.querySelector('.toc-toggle-btn');
  var tocContent = document.querySelector('.toc-content');
  if (tocToggle && tocContent) {
    tocToggle.addEventListener('click', function () {
      var isCollapsed = tocContent.classList.contains('collapsed');
      tocContent.classList.toggle('collapsed');
      tocToggle.classList.toggle('collapsed', isCollapsed);
      tocToggle.setAttribute('aria-expanded', isCollapsed);
    });
  }

  document.querySelectorAll('.sidebar-tab-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var panelName = btn.getAttribute('data-tab');
      var allBtns = document.querySelectorAll('.sidebar-tab-btn');
      var allPanels = document.querySelectorAll('.sidebar-tab-panel');

      allBtns.forEach(function (el) {
        el.classList.remove('active');
        el.setAttribute('aria-selected', 'false');
      });
      allPanels.forEach(function (panel) {
        panel.classList.remove('active');
      });

      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');

      allPanels.forEach(function (panel) {
        if (panel.getAttribute('data-panel') === panelName) {
          panel.classList.add('active');
        }
      });
    });
  });

  document.querySelectorAll('.dropdown').forEach(function (item) {
    var button = item.querySelector('.nav-dropdown-btn');
    var menu = item.querySelector('.dropdown-menu');
    if (!button || !menu) return;

    button.addEventListener('click', function (event) {
      event.preventDefault();
      var isOpen = menu.classList.contains('open');
      document.querySelectorAll('.dropdown-menu').forEach(function (el) {
        el.classList.remove('open');
      });
      menu.classList.toggle('open', !isOpen);
      button.setAttribute('aria-expanded', !isOpen);
    });

    menu.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        menu.classList.remove('open');
        button.setAttribute('aria-expanded', 'false');
      });
    });
  });

  document.addEventListener('click', function (event) {
    if (!event.target.closest('.dropdown')) {
      document.querySelectorAll('.dropdown-menu').forEach(function (el) {
        el.classList.remove('open');
      });
    }
  });

  if (searchInput) {
    searchInput.addEventListener('focus', function () {
      this.parentElement.style.borderColor = 'var(--accent)';
    });

    searchInput.addEventListener('blur', function () {
      this.parentElement.style.borderColor = '';
    });
  }
});
